      "ar": "قُلْ أَرَءَيْتُم مَّا أَنزَلَ اللَّهُ لَكُم مِّن رِّزْقٍ فَجَعَلْتُم مِّنْهُ حَرَامًا وَحَلَٰلًا قُلْ ءَاللَّهُ أَذِنَ لَكُمْ أَمْ عَلَى اللَّهِ تَفْتَرُونَ",
      "translit": "Qul araʾaytum mā anzala llāhu lakum min rizqin fajaʿaltum minhu ḥarāman waḥalālan qul ālllāhu adhina lakum am ʿalā llāhi taftarūn",
