        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Onların ardından da Firavun ve erkanına ayetlerimizle Musa ve Harun'u gönderdik. Ama büyüklük tasladılar ve suçlu bir millet oldular"
        }
